  'my.title': 'ಸೆಟ್ಟಿಂಗ್ ಮತ್ತು ಸೇವ್ ಮಾಡಿದ ಡೇಟಾ', 'my.intro': 'Nivesh Sahayak ನ ಪ್ರತಿ ಡಾಕ್ಯುಮೆಂಟ್ ಟೂಲ್ ಅನ್ನು ಒಂದೇ ಕಡೆ ಸೆಟ್ ಮಾಡಿ: ನಿಮ್ಮ ಬಿಸಿನೆಸ್‌ಗಳು, ಗ್ರಾಹಕರು ಮತ್ತು ಸಪ್ಲೈಯರ್‌ಗಳು, ಐಟಂ ಮತ್ತು ಸರ್ವಿಸ್, ನಂಬರಿಂಗ್ ಮತ್ತು ಡೀಫಾಲ್ಟ್. ಎಲ್ಲವೂ ಇದೇ ಬ್ರೌಸರ್‌ನಲ್ಲಿ ಇರುತ್ತದೆ. ನಮಗೆ ಏನೂ ಕಳುಹಿಸಲಾಗುವುದಿಲ್ಲ.',
