  "hub.g.pre": "ಇತರ ಡಾಕ್ಯುಮೆಂಟ್‌ಗಳ ನಂಬರ್ ಪ್ರಿಫಿಕ್ಸ್",
  "hub.h.pre": "ಅಂಕಿಗಳು ಮತ್ತು ಫೈನಾನ್ಶಿಯಲ್ ಇಯರ್ ಮೇಲಿನ ಇನ್‌ವಾಯ್ಸ್ ನಂಬರಿಂಗ್ ಅನ್ನೇ ಅನುಸರಿಸುತ್ತವೆ. ಪ್ರಿಫಿಕ್ಸ್ ಇಲ್ಲದ ನಂಬರ್‌ಗೆ ಬಾಕ್ಸ್ ಖಾಲಿ ಬಿಡಿ.",
  /* tax rule fixes (Tax research, 4 Nov 2026) */
  "ei.aato": "ನಿಮ್ಮ ಟರ್ನ್‌ಓವರ್",
  "ei.a.none": "ಗೊತ್ತಿಲ್ಲ / ಸೆಟ್ ಮಾಡಿಲ್ಲ",
  "ei.a.lt5": "2017-18 ರಿಂದ ಯಾವ ವರ್ಷವೂ ₹5 ಕೋಟಿ ದಾಟಿಲ್ಲ",
  "ei.a.5to10": "ಯಾವುದೋ ಒಂದು ವರ್ಷ ₹5 ಕೋಟಿ ದಾಟಿದೆ, ಕಳೆದ ವರ್ಷ ₹10 ಕೋಟಿಗಿಂತ ಕಡಿಮೆ",
  "ei.a.10p": "₹10 ಕೋಟಿ ಅಥವಾ ಹೆಚ್ಚು",
  "ei.h.aato": "ಇ-ಇನ್‌ವಾಯ್ಸ್ ನಿಮಗೆ ಅನ್ವಯವಾಗುತ್ತದೆಯೇ, 30 ದಿನದ ಮಿತಿ ಅನ್ವಯವಾಗುತ್ತದೆಯೇ ಎಂಬುದನ್ನು ಇದು ನಿರ್ಧರಿಸುತ್ತದೆ. ಇದು ಇದೇ ಬ್ರೌಸರ್‌ನಲ್ಲಿ ನೆನಪಿರುತ್ತದೆ.",
  "ev.hsn6": "ಐಟಂ {n}: ಇ-ಇನ್‌ವಾಯ್ಸ್‌ಗೆ 6 ಅಥವಾ 8 ಅಂಕಿಯ HSN/SAC ಕೋಡ್ ಬೇಕು (4 ಅಂಕಿ ₹5 ಕೋಟಿಗಿಂತ ಕಡಿಮೆ, ಇ-ಇನ್‌ವಾಯ್ಸ್ ಮಾಡದ ಬಿಸಿನೆಸ್‌ಗೆ ಮಾತ್ರ).",
  "ev.old30": "ಈ ಇನ್‌ವಾಯ್ಸ್ 30 ಅಥವಾ ಹೆಚ್ಚು ದಿನ ಹಳೆಯದು. ₹10 ಕೋಟಿ ಅಥವಾ ಹೆಚ್ಚು ಟರ್ನ್‌ಓವರ್ ಇದ್ದರೆ ಪೋರ್ಟಲ್ ಇದನ್ನು ಇನ್ನು ರಿಜಿಸ್ಟರ್ ಮಾಡುವುದಿಲ್ಲ. ಹೊಸ ಇನ್‌ವಾಯ್ಸ್ ಮಾಡುವ ಮೊದಲು ನಿಮ್ಮ ಅಕೌಂಟೆಂಟ್ ಅನ್ನು ಕೇಳಿ.",
  "ev.lt5": "2017-18 ರಿಂದ ಯಾವ ವರ್ಷದಲ್ಲೂ ನಿಮ್ಮ ಟರ್ನ್‌ಓವರ್ ₹5 ಕೋಟಿ ದಾಟದಿದ್ದರೆ ಇ-ಇನ್‌ವಾಯ್ಸ್ ನಿಮಗೆ ಕಡ್ಡಾಯವಲ್ಲ.",
  "ev.old180": "180 ದಿನಕ್ಕಿಂತ ಹಳೆಯ ಡಾಕ್ಯುಮೆಂಟ್‌ಗೆ ಪೋರ್ಟಲ್ ಇ-ವೇ ಬಿಲ್ ಮಾಡುವುದಿಲ್ಲ.",
  "ev.smallst": "{st} ಒಳಗೆ ಇ-ವೇ ಬಿಲ್ ಸಾಮಾನ್ಯವಾಗಿ ₹{v} ಗಿಂತ ಹೆಚ್ಚಾದರೆ ಮಾತ್ರ ಬೇಕು (ಬೇರೆ ರಾಜ್ಯಕ್ಕೆ ₹50,000 ಗಿಂತ ಹೆಚ್ಚು; ಬೇರೆ ರಾಜ್ಯಕ್ಕೆ ಹೋಗುವ ಜಾಬ್ ವರ್ಕ್, ಕರಕುಶಲ ವಸ್ತುಗಳಿಗೆ ಯಾವುದೇ ಮೊತ್ತಕ್ಕೂ ಬೇಕು).",
  "ev.fromirn": "ನಿಮ್ಮ ಬಿಸಿನೆಸ್ ಇ-ಇನ್‌ವಾಯ್ಸ್ ಮಾಡಬೇಕಿದ್ದರೆ, ಈ ಇನ್‌ವಾಯ್ಸ್‌ನ ಇ-ವೇ ಬಿಲ್ ಅನ್ನು ಪೋರ್ಟಲ್ ಅದರ IRN ನಿಂದ ಮಾತ್ರ ಮಾಡುತ್ತದೆ: “ಇ-ಇನ್‌ವಾಯ್ಸ್ ಜೊತೆಗೆ ಇ-ವೇ ಬಿಲ್ ಕೂಡ ಮಾಡಿ” ಟಿಕ್ ಮಾಡಿ ಇ-ಇನ್‌ವಾಯ್ಸ್ ಫೈಲ್ ಮಾಡಿ.",
  "ev.tidchk": "ಟ್ರಾನ್ಸ್‌ಪೋರ್ಟರ್ ID ಯ ಕೊನೆಯ ಅಕ್ಷರ ಹೊಂದುತ್ತಿಲ್ಲ. ಟೈಪಿಂಗ್ ತಪ್ಪೇ ಎಂದು ಒಮ್ಮೆ ಪರಿಶೀಲಿಸಿ.",
  "ei.rmnote": "ನೀವು ಈ IRN ಅನ್ನು ಪೋರ್ಟಲ್‌ನಲ್ಲಿ ಕ್ಯಾನ್ಸಲ್ ಮಾಡಿದ್ದರೆ, ಈ ಇನ್‌ವಾಯ್ಸ್ ನಂಬರ್ ಮತ್ತೆ ಎಂದಿಗೂ ರಿಜಿಸ್ಟರ್ ಆಗುವುದಿಲ್ಲ. ಸರಿಯಾದ ಇನ್‌ವಾಯ್ಸ್ ಅನ್ನು ಹೊಸ ನಂಬರ್‌ನಲ್ಲಿ ಮಾಡಿ.",
  /* tax rule fixes, bills (4 Nov 2026) */
  "hub.reg": "GST ನೋಂದಣಿ",
  "hub.rg.regular": "ರೆಗ್ಯುಲರ್ GST ನೋಂದಣಿ",
