  "v.recv": "ಸರಕು ಅಥವಾ ಸರ್ವಿಸ್ ಬಂದ ದಿನಾಂಕ ಟೈಪ್ ಮಾಡಿ.",
  "c.si30": "ಈ ಸೆಲ್ಫ್ ಇನ್‌ವಾಯ್ಸ್‌ನ ದಿನಾಂಕ, ಸರಕು ಅಥವಾ ಸರ್ವಿಸ್ ಬಂದು 30 ದಿನಗಳ ನಂತರ ಇದೆ. ನಿಯಮದಂತೆ 30 ದಿನಗಳೊಳಗೆ ಮಾಡಬೇಕು. ಆದರೂ ಸೇವ್ ಮಾಡಬೇಕೇ?",
  "k.ref": "ಅಡ್ವಾನ್ಸ್ ವಾಪಸ್",
  "kh.ref": "ಏನೂ ಸಪ್ಲೈ ಆಗದ ಕಾರಣ ವಾಪಸ್ ಕೊಟ್ಟ ಅಡ್ವಾನ್ಸ್ ಹಣ. GST ನಿಯಮಗಳು ಇದನ್ನು ರೀಫಂಡ್ ವೋಚರ್ ಎನ್ನುತ್ತವೆ.",
  "s.gstadv": "ಈ ಅಡ್ವಾನ್ಸ್‌ನಲ್ಲಿ GST ಸೇರಿದೆ (ಸರ್ವಿಸ್)",
  "s.h.gstadv": "ಸರ್ವಿಸ್‌ಗಾಗಿ ಬಂದ ಅಡ್ವಾನ್ಸ್‌ಗೆ ಟಿಕ್ ಮಾಡಿ: ಆಗ ರಸೀದಿ, ಅದರೊಳಗಿನ GST ತೋರಿಸುವ ರಸೀದಿ ವೋಚರ್ ಆಗುತ್ತದೆ. ಸರಕಿನ ಅಡ್ವಾನ್ಸ್‌ಗೆ GST ಇಲ್ಲ; ಸಾಮಾನ್ಯ ಅಡ್ವಾನ್ಸ್ ರಸೀದಿಯೇ ರಸೀದಿ ವೋಚರ್ ಆಗಿ ಕೆಲಸ ಮಾಡುತ್ತದೆ.",
  "s.samestate": "ನನ್ನ ರಾಜ್ಯವೇ",
  "s.sacf": "SAC ಕೋಡ್",
  "s.rv": "ರಸೀದಿ ವೋಚರ್ ನಂಬರ್",
  "s.h.rv": "ಅಡ್ವಾನ್ಸ್ ಬಂದಾಗ ನೀವು ಕೊಟ್ಟ ರಸೀದಿ ವೋಚರ್.",
  "s.rvdate": "ರಸೀದಿ ವೋಚರ್ ದಿನಾಂಕ",
  "s.v.rv": "ಈ ರೀಫಂಡ್ ಯಾವ ರಸೀದಿ ವೋಚರ್‌ಗಾಗಿ ಎಂದು ಅದರ ನಂಬರ್ ಟೈಪ್ ಮಾಡಿ.",
  "s.lg.tdsrcm": "TDS ಮತ್ತು ರಿವರ್ಸ್ ಚಾರ್ಜ್",
  "s.tdssec": "TDS ಸೆಕ್ಷನ್",
  "s.h.tdssec": "ಸೆಕ್ಷನ್ ಆಯ್ಕೆ ಮಾಡಿ ಅಥವಾ ಟೈಪ್ ಮಾಡಿ, ಉದಾಹರಣೆಗೆ 393 (ಹಳೆಯ 194C). ಸಂಶಯ ಇದ್ದರೆ ನಿಮ್ಮ ಅಕೌಂಟೆಂಟ್ ಅನ್ನು ಕೇಳಿ.",
  "s.tdsrate": "TDS ರೇಟ್ %",
