  "s.rcm": "ಈ ಪಾವತಿಯ GST ನಾವೇ ಕಟ್ಟಬೇಕು (ರಿವರ್ಸ್ ಚಾರ್ಜ್)",
  "s.h.rcm": "ಉದಾಹರಣೆಗೆ ನೋಂದಣಿ ಇಲ್ಲದ ಸಪ್ಲೈಯರ್‌ಗೆ ಅಥವಾ ರಿವರ್ಸ್ ಚಾರ್ಜ್‌ನಲ್ಲಿರುವ ಗೂಡ್ಸ್ ಟ್ರಾನ್ಸ್‌ಪೋರ್ಟ್ ಏಜೆನ್ಸಿಗೆ ಪಾವತಿ.",
  "s.rcmrate": "ರಿವರ್ಸ್ ಚಾರ್ಜ್ GST ರೇಟ್ %",
  "c.nopan": "ನೀವು TDS ಕಡಿತ ಮಾಡುತ್ತಿದ್ದೀರಿ, ಆದರೆ ಹಣ ಪಡೆಯುವವರ PAN ಖಾಲಿ ಇದೆ. PAN ಇಲ್ಲದೆ TDS ಸಾಮಾನ್ಯವಾಗಿ 20% (ಸರಕು ಖರೀದಿಗೆ 5%). ಆದರೂ ಸೇವ್ ಮಾಡಬೇಕೇ?",
  "s.sum.net2": "ನೆಟ್ ಪಾವತಿ {v}",
