  "g3.formh": "ಸೇವ್ ಮಾಡಿದ ಬಿಲ್‌ಗಳ ಅಂಕಿಗಳು ತುಂಬಿವೆ. ಯಾವುದೇ ಬಾಕ್ಸ್ ಮೇಲೆ ಟೈಪ್ ಮಾಡಬಹುದು, ಉದಾಹರಣೆಗೆ ನಿಮ್ಮ GSTR-2B ನಲ್ಲಿ ತೋರಿಸಿದ ITC. ನೀವು ಬದಲಿಸಿದ ಬಾಕ್ಸ್‌ಗಳಿಗೆ ಗುರುತು ಇರುತ್ತದೆ.",
