  "td.k.tds": "ಕಡಿತ ಮಾಡಬೇಕಾದ TDS",
  "td.k.rate": "ದರ",
  "td.k.pay": "ಪೇಮೆಂಟ್ ಪಡೆಯುವವರಿಗೆ ಕೊಡಬೇಕಾದದ್ದು",
  "td.k.dep": "TDS ಜಮೆ ಮಾಡುವ ಕೊನೆಯ ದಿನ",
  "td.line": "TDS = {b} ರ {r}% = {t}. ಈ ಬಿಲ್ ಅನ್ನು ಅದರ GST {g} ಜೊತೆ, TDS ಕಳೆದು ಕೊಡಿ: {p}.",
  "td.no.c": "TDS ಇಲ್ಲ: ಈ ಬಿಲ್ ₹30,000 ಅಥವಾ ಕಡಿಮೆ ಮತ್ತು ವರ್ಷದ ಒಟ್ಟು ₹1,00,000 ಒಳಗೇ ಇದೆ.",
  "td.no.m": "TDS ಇಲ್ಲ: ತಿಂಗಳ ಪೇಮೆಂಟ್ {l} ಕ್ಕಿಂತ ಹೆಚ್ಚಿಲ್ಲ.",
  "td.no.y": "ಇನ್ನೂ TDS ಇಲ್ಲ: ವರ್ಷದ ಒಟ್ಟು {l} ಒಳಗೇ ಇದೆ. ಅದನ್ನು ದಾಟಿಸುವ ಪೇಮೆಂಟ್‌ನಲ್ಲಿ ಕಡಿತ ಮಾಡಿ.",
  "td.no.q": "ಇನ್ನೂ TDS ಇಲ್ಲ: ಈ ವರ್ಷ ಈ ಮಾರಾಟಗಾರರಿಂದ ಖರೀದಿ {l} ಕ್ಕಿಂತ ಹೆಚ್ಚಿಲ್ಲ.",
  "td.catch": "ಈ ಪೇಮೆಂಟ್ ವರ್ಷದ ಒಟ್ಟನ್ನು ಮಿತಿಗಿಂತ ಮೇಲೆ ಒಯ್ಯುತ್ತದೆ, ಆದ್ದರಿಂದ TDS ಪೂರ್ತಿ ಒಟ್ಟಿನ ಮೇಲೆ ಲೆಕ್ಕ ಹಾಕಲಾಗಿದೆ, TDS ಇಲ್ಲದೆ ಮೊದಲು ಕೊಟ್ಟ {y} ಸೇರಿ. ಅದರಲ್ಲಿ ಸ್ವಲ್ಪಕ್ಕೆ ಈಗಾಗಲೇ TDS ಕಡಿತ ಮಾಡಿದ್ದರೆ, ವ್ಯತ್ಯಾಸವನ್ನು ಮಾತ್ರ ಕಡಿತ ಮಾಡಿ.",
  "td.nopan": "ಸರಿಯಾದ PAN ಇಲ್ಲದಿದ್ದರೆ ದರ 20% ಅಥವಾ ಸಾಮಾನ್ಯ ದರದ ಎರಡರಷ್ಟು (ಸರಕು ಖರೀದಿಗೆ 5%), ಇವುಗಳಲ್ಲಿ ಹೆಚ್ಚಿನದು. ಪೇಮೆಂಟ್ ಪಡೆಯುವವರಿಂದ PAN ಕೇಳಿ.",
  "td.trans": "10 ಅಥವಾ ಕಡಿಮೆ ಗೂಡ್ಸ್ ವಾಹನಗಳಿರುವ ಟ್ರಾನ್ಸ್‌ಪೋರ್ಟರ್ PAN ಸಹಿತ ಘೋಷಣೆ ಕೊಟ್ಟರೆ TDS ಇಲ್ಲದೆ ಪೇಮೆಂಟ್ ಮಾಡಬಹುದು.",
  "td.q": "ಕಳೆದ ವರ್ಷ ನಿಮ್ಮ ಟರ್ನ್‌ಓವರ್ ₹10 ಕೋಟಿಗಿಂತ ಹೆಚ್ಚಿದ್ದರೆ ಮಾತ್ರ, ಮತ್ತು ಈ ಮಾರಾಟಗಾರರಿಂದ ವರ್ಷದ ಖರೀದಿಯಲ್ಲಿ ₹50 ಲಕ್ಷಕ್ಕಿಂತ ಮೇಲಿನ ಭಾಗದ ಮೇಲೆ ಮಾತ್ರ ಕಡಿತ ಮಾಡಿ.",
  "td.ib": "ಟ್ಯಾಕ್ಸ್ ಆಡಿಟ್ ಇಲ್ಲದ ವ್ಯಕ್ತಿ ಕೊಡುವ ಬಾಡಿಗೆಗೆ TDS ಒಮ್ಮೆ ಮಾತ್ರ ಕಡಿತ ಮಾಡಲಾಗುತ್ತದೆ, ವರ್ಷದ ಅಥವಾ ಬಾಡಿಗೆ ಅವಧಿಯ ಕೊನೆಯ ತಿಂಗಳ ಬಾಡಿಗೆಯಿಂದ.",
  "td.oldnote": "2026 ಏಪ್ರಿಲ್ 1 ರ ಮೊದಲಿನ ಪೇಮೆಂಟ್‌ಗಳಿಗೆ ಆದಾಯ ತೆರಿಗೆ ಕಾಯ್ದೆ, 1961 ಅನ್ವಯಿಸುತ್ತದೆ: ಹಳೆಯ ಸೆಕ್ಷನ್ ನಂಬರ್ ಬಳಸಿ.",
  "td.h.reg": "ನೀವು ಕಡಿತ ಮಾಡಿದ TDS (ನಿಮ್ಮ ಪೇಮೆಂಟ್ ವೋಚರ್‌ಗಳಿಂದ)",
  "td.h.regh": "voucher.niveshsahayak.in ನಲ್ಲಿ ಅಥವಾ ಆ್ಯಪ್‌ನಲ್ಲಿ TDS ದರದೊಂದಿಗೆ ಸೇವ್ ಮಾಡಿದ ವೋಚರ್‌ಗಳು, ತಿಂಗಳು ಮತ್ತು ಸೆಕ್ಷನ್ ಪ್ರಕಾರ, ಜಮೆ ಮಾಡುವ ದಿನಾಂಕದ ಜೊತೆ.",
  "td.h.cut": "ಗ್ರಾಹಕರು ನಿಮ್ಮಿಂದ ಕಡಿತ ಮಾಡಿದ TDS (ನಿಮ್ಮ ರಸೀದಿಗಳಿಂದ)",
  "td.h.cuth": "“TDS deducted by payer” ಇರುವ ರಸೀದಿಗಳು. ಕ್ಲೈಮ್ ಮಾಡುವ ಮೊದಲು ಪ್ರತಿಯೊಂದೂ ನಿಮ್ಮ ವಾರ್ಷಿಕ ಟ್ಯಾಕ್ಸ್ ಸ್ಟೇಟ್‌ಮೆಂಟ್‌ನಲ್ಲಿ ಕಾಣುತ್ತದೆಯೇ ಎಂದು ನೋಡಿ.",
